import React, { useState, useEffect } from "react";
import Navbar from "./Navbar";
import Footer from "./Footer";
import { NavLink } from 'react-router-dom';
import jwtDecode from "jwt-decode";

function DashboardSales() {
  const [sales, setSales] = useState([]);

  // Get current user from token
  const token = localStorage.getItem("token");
  let currentUser = null;
  try {
    currentUser = jwtDecode(token);
  } catch (err) {
    console.error("Invalid token");
  }

  useEffect(() => {
    if (!currentUser) return;

    const fetchSales = async () => {
      try {
        const response = await fetch(`http://localhost:5009/api/orders/sales/${currentUser.id}`);
        const data = await response.json();
        setSales(Array.isArray(data) ? data : []);
      } catch (err) {
        console.error("Failed to fetch sales:", err);
        setSales([]);
      }
    };

    fetchSales();
  }, [currentUser]);

  return (
    <>
      <Navbar />
      <div className="KO">
        <div className="Mother">
          <div className="Sidebar">
            <h2 className="dashboard-title">
              <font style={{color: '#eef0bb' }}>A</font>
              <font style={{color: '#fbebc1' }}>d</font>
              <font style={{color: '#bcdef4'}}>m</font>
              <font style={{color: '#e4c8e0'}}>i</font>
              <font style={{color: '#fac7c7'}}>n</font> Hub
            </h2>

            <NavLink to="/AdminHub" className={({ isActive }) => isActive ? "nav-links active" : "nav-links"}>Dashboard</NavLink>
            <NavLink to="/DashboardBooks" className={({ isActive }) => isActive ? "nav-links active" : "nav-links"}>Add Books</NavLink>
            <NavLink to="/DashboardBooksList" className={({ isActive }) => isActive ? "nav-links active" : "nav-links"}>My Listings</NavLink>
            <NavLink to="/DashboardSales" className={({ isActive }) => isActive ? "nav-links active" : "nav-links"}>Sales</NavLink>
            <NavLink to="/" className="nav-link return-main">Return to Main Site</NavLink>
            <NavLink to="/" className="nav-link return-main">Log Out</NavLink>
          </div>

          <div className="Daughter">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-gray-100">
                  <th className="p-3">Buyer Email</th>
                  <th className="p-3">Book</th>
                  <th className="p-3">Price</th>
                  <th className="p-3">Purchased At</th>
                </tr>
              </thead>
              <tbody>
                {Array.isArray(sales) && sales.length > 0 ? (
                  sales.map((sale) => (
                    <tr key={sale._id} className="border-t">
                      <td className="p-3 text-gray-600">{sale.buyerEmail}</td>
                      <td className="p-3 text-gray-600">{sale.title}</td>
                      <td className="p-3 font-semibold text-indigo-600">${sale.price}</td>
                      <td className="p-3 text-gray-500">{new Date(sale.purchasedAt).toLocaleString()}</td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="4" className="p-3 text-center text-gray-500">
                      No sales found
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
      <Footer />
    </>
  );
}

export default DashboardSales;
